"""Regenerate original local demonstration illustrations; no reference photos are reused."""
from pathlib import Path
import html
ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / 'assets'
ASSETS.mkdir(exist_ok=True)
def svg(name, inner, width=800, height=600):
    (ASSETS / name).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">{inner}</svg>')
